SELECT COUNT(1) FROM `warehouse_record`
WHERE item_id = #{itemId}
  AND (related_fault_id IS NOT NULL OR related_plot_id IS NOT NULL OR related_task_id IS NOT NULL)

SELECT 
FROM `warehouse_record` wr


    AND wi.farm_owner_id = #{userId}
    AND wr.item_id = #{itemId}
    AND wi.item_name LIKE CONCAT('%', #{itemName}, '%')
    AND wr.record_type = #{recordType}
    AND wr.record_time >= #{startTime}
    AND wr.record_time <= #{endTime}
    AND wr.status = 1

ORDER BY wr.record_time DESC, wr.id DESC

SELECT COALESCE(SUM(quantity), 0)
FROM `warehouse_record` wr
JOIN `warehouse_item` wi ON wi.id = wr.item_id

    AND wi.farm_owner_id = #{userId}
    AND wr.record_type = #{recordType}
    AND wr.status = 1

SELECT COALESCE(SUM(quantity), 0)
FROM `warehouse_record` wr
JOIN `warehouse_item` wi ON wi.id = wr.item_id
WHERE wr.record_type = #{recordType}
  AND wr.record_time >= #{startTime}
  AND wr.record_time < #{endTime}
  AND wr.status = 1
AND wi.farm_owner_id = #{userId}

SELECT COALESCE(SUM(wr.quantity), 0)
FROM `warehouse_record` wr
JOIN `warehouse_item` wi ON wi.id = wr.item_id
WHERE wi.is_deleted = 0 AND wi.farm_owner_id IS NOT NULL
  AND wr.record_type = #{recordType}
  AND wr.record_time >= #{startTime}
  AND wr.record_time < #{endTime}
  AND wr.status = 1
AND wi.farm_owner_id = #{farmOwnerId}
